import json,hashlib
from pathlib import Path
d=json.loads(Path('work/focused-successor/specialist-proposal.json').read_text(encoding='utf-8'))
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
print("== assignment/state/context_packet/conventions ==")
print(json.dumps({k:d[k] for k in ['assignment','state','context_packet','conventions']},indent=1))
print("== sources (verify) ==")
for sid,s in d['sources'].items():
    p=s.get('path'); ok=None
    try: ok = sha(p)==s.get('sha256')
    except Exception as e: ok=f"ERR {e}"
    print(sid, '|', p, '|', s.get('sha256','')[:12], '| match=',ok, '|', s.get('role'))
    extra={k:v for k,v in s.items() if k not in ('path','sha256','role')}
    if extra: print('    extra:', json.dumps(extra)[:400])
EOF

